function completedModes(){try{return new Set(JSON.parse(localStorage.getItem('swarmfall-modes')||'[]'))}catch{return new Set()}}
function accountProgress(type,payload,onEnqueued,onRejected,operationId){let accepted=false,settled=false;const queued=operation=>{if(settled)return;settled=true;accepted=true;onEnqueued?.(operation)},rejected=error=>{if(settled)return;settled=true;onRejected?.(error)};try{Promise.resolve(window.SwarmAccount?.progress(type,payload,queued,rejected,operationId)).catch(error=>{rejected(error);return Promise.resolve(window.SwarmAccount?.sync?.()).catch(()=>{})})}catch(error){rejected(error)}return accepted}
function singleplayerTerminalKey(){return singleplayerAccountId?`${TERMINAL_KEY}:${singleplayerAccountId}`:null}
function readSingleplayerTerminal(){const key=singleplayerTerminalKey();if(!key)return null;try{const value=JSON.parse(localStorage.getItem(key)||'null');return value?.version===1&&['victory','death','quit'].includes(value.kind)&&value.result?.id?value:null}catch{return null}}
function persistSingleplayerTerminal(){const key=singleplayerTerminalKey();if(!singleplayerTerminalDescriptor||!key)return false;try{localStorage.setItem(key,JSON.stringify(singleplayerTerminalDescriptor));return true}catch{return false}}
function restoreSingleplayerTerminal(){const value=readSingleplayerTerminal();if(!value)return;singleplayerTerminalDescriptor=value;singleplayerTerminalVictory=value.kind==='victory';singleplayerResultPayload=value.result.payload;singleplayerResultOperationId=value.result.id;singleplayerResultState=value.result.queued?'queued':'idle';if(value.completeMap){singleplayerCompleteMapPayload=value.completeMap.payload;singleplayerCompleteMapOperationId=value.completeMap.id;singleplayerCompleteMapState=value.completeMap.queued?'queued':'idle'}}
function queueSingleplayerResultOnce(){if(singleplayerResultState==='queued')return true;if(singleplayerResultState!=='idle')return false;singleplayerResultPayload??={time:Math.floor(elapsed),kills:player.kills,character:chosenCharacter};singleplayerResultState='enqueueing';accountProgress('awardSingleplayerResult',singleplayerResultPayload,()=>{singleplayerResultState='queued';if(singleplayerTerminalDescriptor){singleplayerTerminalDescriptor.result.queued=true;persistSingleplayerTerminal()}},()=>{if(singleplayerResultState==='enqueueing')singleplayerResultState='idle'},singleplayerResultOperationId);return singleplayerResultState==='queued'}
function queueSingleplayerCompleteMapOnce(){if(singleplayerCompleteMapState==='queued')return true;if(singleplayerCompleteMapState!=='idle')return false;singleplayerCompleteMapPayload??={map:chosenMap,mode:chosenMode};singleplayerCompleteMapState='enqueueing';accountProgress('completeMap',singleplayerCompleteMapPayload,()=>{singleplayerCompleteMapState='queued';if(singleplayerTerminalDescriptor){singleplayerTerminalDescriptor.completeMap.queued=true;persistSingleplayerTerminal()}},()=>{if(singleplayerCompleteMapState==='enqueueing')singleplayerCompleteMapState='idle'},singleplayerCompleteMapOperationId);return singleplayerCompleteMapState==='queued'}
function queueRequiredSingleplayerOperations(){return queueSingleplayerResultOnce()&&(!singleplayerTerminalVictory||queueSingleplayerCompleteMapOnce())}
function beginSingleplayerTerminal(victory=false,kind=victory?'victory':'death'){running=false;paused=true;singleplayerTerminalVictory=victory;if(!singleplayerTerminalDescriptor){const id=crypto.randomUUID();singleplayerResultPayload={time:Math.floor(elapsed),kills:player.kills,character:chosenCharacter};singleplayerResultOperationId=`${id}-result`;singleplayerCompleteMapPayload=victory?{map:chosenMap,mode:chosenMode}:null;singleplayerCompleteMapOperationId=victory?`${id}-map`:null;singleplayerTerminalDescriptor={version:1,id,kind,result:{id:singleplayerResultOperationId,payload:singleplayerResultPayload,queued:false},completeMap:victory?{id:singleplayerCompleteMapOperationId,payload:singleplayerCompleteMapPayload,queued:false}:null};if(!persistSingleplayerTerminal())return false}return queueRequiredSingleplayerOperations()}
function retrySingleplayerResultAndReload(){if(queueRequiredSingleplayerOperations()){clearGameSave();try{localStorage.removeItem(singleplayerTerminalKey())}catch{}singleplayerTerminalDescriptor=null;location.reload()}}
