let assetLoadGeneration=0,assetRetryAction=null;
function setAssetLoading(state,{progress=0,status=t('assets.preparing')}={}){const overlay=document.querySelector('#assetLoading'),retry=document.querySelector('#assetLoadingRetry');overlay.classList.toggle('hidden',state==='hidden');overlay.setAttribute('aria-busy',state==='loading'?'true':'false');document.querySelector('#assetLoadingStatus').textContent=status;document.querySelector('#assetLoadingBar').style.width=`${Math.round(progress*100)}%`;document.querySelector('#assetLoadingPercent').textContent=`${Math.round(progress*100)}%`;retry.classList.toggle('hidden',state!=='failed')}
async function enterWithAssets(spec,action,manual=false){const generation=++assetLoadGeneration;assetRetryAction=()=>enterWithAssets(spec,action,true);setAssetLoading('loading');try{const wait=manual?SwarmAssets.retryFailed:SwarmAssets.waitForRequired;await wait(spec,{onProgress:value=>{if(generation===assetLoadGeneration)setAssetLoading(value.status,{progress:value.progress,status:t(value.status==='failed'?'assets.loadFailed':'assets.loadingSet')})}});if(generation!==assetLoadGeneration)return;setAssetLoading('hidden',{progress:1});action()}catch(error){if(error.cancelled||generation!==assetLoadGeneration)return;setAssetLoading('failed',{status:t('assets.retryLong')})}}
