function drawScenery(s){
  if(chosenMap==='ruins'){window.SwarmMapVisuals?.drawScenery(ctx,s);return;}
  ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.rot);
  if(s.type==='crystal'||s.type==='toxicCrystal'){ctx.shadowBlur=16;ctx.shadowColor=s.type==='toxicCrystal'?'rgba(156,255,69,.45)':'rgba(43,192,191,.35)';ctx.fillStyle=s.type==='toxicCrystal'?'#263b18':'#122f3b';ctx.strokeStyle=s.type==='toxicCrystal'?'#76c746':'#277a83';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-s.size);ctx.lineTo(s.size*.55,4);ctx.lineTo(s.size*.25,s.size*.65);ctx.lineTo(-s.size*.38,s.size*.45);ctx.lineTo(-s.size*.55,0);ctx.closePath();ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(0,-s.size);ctx.lineTo(0,s.size*.45);ctx.lineTo(s.size*.55,4);ctx.stroke()}
  else{ctx.fillStyle='#131d2e';ctx.strokeStyle='#344860';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,s.size,0,7);ctx.fill();ctx.stroke();ctx.strokeStyle='#51f6df44';for(let i=0;i<6;i++){ctx.rotate(Math.PI/3);ctx.beginPath();ctx.moveTo(s.size*.3,0);ctx.lineTo(s.size*.78,0);ctx.stroke()}ctx.fillStyle='#050912';ctx.beginPath();ctx.arc(0,0,s.size*.3,0,7);ctx.fill()}
  ctx.restore();
}
function drawLoot(item){const y=item.y+Math.sin(elapsed*4+item.bob)*4,color=item.type==='health'?'#ff6688':item.type==='xp'?'#51f6df':'#ffd467';ctx.save();ctx.translate(item.x,y);ctx.shadowBlur=20;ctx.shadowColor=color;ctx.fillStyle=color;if(item.type==='health'){ctx.fillRect(-3,-10,6,20);ctx.fillRect(-10,-3,20,6)}else if(item.type==='xp'){ctx.rotate(Math.PI/4);ctx.fillRect(-7,-7,14,14)}else if(item.type==='coin'){ctx.rotate(elapsed*1.8);ctx.beginPath();for(let i=0;i<6;i++){const a=i*Math.PI/3;ctx.lineTo(Math.cos(a)*11,Math.sin(a)*11)}ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#fff0a0';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#33280d';ctx.fillRect(-2,-5,4,10);ctx.fillRect(-5,-2,10,4)}else{ctx.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?5:11;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill()}ctx.restore()}
function drawCrate(c){if(chosenMap==='ruins'){window.SwarmMapVisuals?.drawCrate(ctx,c);return;}ctx.save();ctx.translate(c.x,c.y);ctx.shadowBlur=c.opened?5:14;ctx.shadowColor=c.reward==='health'?'#ff6688':c.reward==='level'?'#ffd467':'#d99b45';ctx.fillStyle=c.hit?'#fff':c.opened?'#151b24':'#49351e';ctx.strokeStyle=c.opened?'#394657':'#d39a48';ctx.lineWidth=2;ctx.fillRect(-17,-14,34,28);ctx.strokeRect(-17,-14,34,28);ctx.fillStyle=c.opened?'#0b0e14':'#8c612c';ctx.fillRect(-3,-14,6,28);ctx.fillRect(-17,-3,34,6);if(c.opened){ctx.rotate(-.5);ctx.fillStyle='#293342';ctx.fillRect(-18,-21,36,7)}else{ctx.fillStyle='#ffd071';ctx.beginPath();ctx.arc(0,0,4,0,7);ctx.fill()}ctx.restore()}
const collisionDebugEnabled=localStorage.getItem('swarmfall-debug-collision')==='1';
function drawCollisionDebug(){if(!collisionDebugEnabled)return;const map=SWARM_SHARED_MAPS[chosenMap];ctx.save();ctx.globalAlpha=.85;ctx.lineWidth=2;ctx.font='700 11px monospace';ctx.textAlign='center';ctx.setLineDash([7,5]);ctx.strokeStyle='#ff4fd8';tracePolygon(ctx,map.shape);ctx.stroke();for(const item of map.terrain||[]){if(item.type==='water'){ctx.strokeStyle='#36d9ff';tracePolygon(ctx,item.points);ctx.stroke()}else if(item.type==='rock'){const rock=SwarmCollision.rockCollider(chosenMap,item);ctx.strokeStyle='#ffd45b';ctx.beginPath();ctx.arc(rock.x,rock.y,rock.radius,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='rgba(255,87,87,.75)';ctx.beginPath();ctx.arc(rock.x,rock.y,rock.radius+player.r,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#fff4aa';ctx.fillRect(rock.x-2,rock.y-2,4,4);ctx.fillText(`R${rock.variant}`,rock.x,rock.y-rock.radius-6);ctx.setLineDash([7,5])}else{ctx.strokeStyle='#ff895b';ctx.strokeRect(item.x,item.y,item.w,item.h);ctx.setLineDash([]);ctx.fillStyle='#fff';ctx.fillRect(item.x+item.w/2-2,item.y+item.h/2-2,4,4);ctx.setLineDash([7,5])}}ctx.setLineDash([]);ctx.strokeStyle='#6dff84';ctx.beginPath();ctx.arc(player.x,player.y,player.r,0,Math.PI*2);ctx.stroke();ctx.restore()}
function drawTerrain(){const started=debugProfileStart();drawTerrainCore();debugProfileEnd('terrain',started)}
function drawMapHazards(){
  if(chosenMap==='toxic'){fogZones.forEach(zone=>{ctx.save();ctx.globalAlpha=.12+.04*Math.sin(elapsed+zone.x);ctx.fillStyle='#8bb58a';ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r,0,Math.PI*2);ctx.fill();ctx.restore()});toxicZones.forEach(zone=>{const pulse=.92+Math.sin(elapsed*2+zone.x)*.05;ctx.save();ctx.globalAlpha=.5;ctx.fillStyle='#5f9f24';ctx.shadowBlur=22;ctx.shadowColor='#8eff38';ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.65;ctx.strokeStyle='#c4ff61';ctx.setLineDash([10,15]);ctx.stroke();ctx.restore()})}
  poisonClouds.forEach(cloud=>{if(window.enemySpriteVisuals?.drawCloud(ctx,cloud,elapsed))return;if(cloud.visual||cloud.nightmare||cloud.fog)return;ctx.save();ctx.globalAlpha=Math.min(.55,cloud.life*.12);ctx.fillStyle=cloud.fog?'#4fbf78':'#83c83d';ctx.shadowBlur=35;ctx.shadowColor=ctx.fillStyle;for(let i=0;i<7;i++){const a=i/7*Math.PI*2+elapsed*.18,r=cloud.r*(.45+(i%3)*.14);ctx.beginPath();ctx.arc(cloud.x+Math.cos(a)*cloud.r*.35,cloud.y+Math.sin(a)*cloud.r*.28,r,0,Math.PI*2);ctx.fill()}ctx.restore()});
  traps.forEach(trap=>{if(window.enemySpriteVisuals?.drawTrap(ctx,trap,elapsed))return;if(trap.visual)return;ctx.save();ctx.translate(trap.x,trap.y);ctx.rotate(elapsed*.7);ctx.strokeStyle=trap.armed>0?'#6d7942':'#d7ff65';ctx.fillStyle='rgba(107,145,42,.35)';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<12;i++){const a=i/12*Math.PI*2,r=i%2?trap.r*.55:trap.r;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill();ctx.stroke();ctx.restore()})
}
function drawWorldEvent(){if(!worldEvent)return;ctx.save();ctx.translate(worldEvent.x,worldEvent.y);const pulse=1+Math.sin(elapsed*6)*.08;ctx.strokeStyle=worldEvent.id==='corrupted_zone'?'#9cff54':'#d77cff';ctx.fillStyle=worldEvent.id==='corrupted_zone'?'rgba(116,210,60,.12)':'rgba(194,91,255,.1)';ctx.shadowBlur=22;ctx.shadowColor=ctx.strokeStyle;ctx.lineWidth=3;ctx.setLineDash([12,8]);ctx.beginPath();ctx.arc(0,0,worldEvent.radius*pulse,0,7);ctx.fill();ctx.stroke();ctx.setLineDash([]);if(worldEvent.prompt){ctx.fillStyle='#fff';ctx.font='800 11px Chakra Petch';ctx.textAlign='center';ctx.fillText(t('game.activate'),0,-worldEvent.radius-12)}ctx.restore()}
function update(dt){const started=debugProfileStart();updateCore(dt);debugProfileEnd('totalUpdate',started)}
function drawFogOverlay(){const staticFog=chosenMap==='toxic'&&fogZones.some(zone=>dist(zone,player)<zone.r),cloudFog=poisonClouds.some(cloud=>cloud.fog&&dist(cloud,player)<cloud.r),hunterNight=worldEvent?.id==='hunter_night';if(!staticFog&&!cloudFog&&!hunterNight)return;ctx.save();const fog=ctx.createRadialGradient(W/2,H/2,55,W/2,H/2,Math.max(W,H)*.62);fog.addColorStop(0,'rgba(13,24,15,.1)');fog.addColorStop(.16,'rgba(34,58,35,.62)');fog.addColorStop(1,'rgba(7,16,10,.97)');ctx.fillStyle=fog;ctx.fillRect(0,0,W,H);ctx.globalAlpha=.18;ctx.fillStyle='#8fcb78';for(let i=0;i<14;i++){const x=(i*211+elapsed*18)%W,y=(i*137+Math.sin(elapsed+i)*80+H)%H;ctx.beginPath();ctx.arc(x,y,90+(i%4)*35,0,Math.PI*2);ctx.fill()}ctx.restore();if(worldEvent?.id==='hunter_night'){ctx.fillStyle='rgba(2,4,10,.58)';ctx.fillRect(0,0,W,H)}}
function drawEnemy(e){
  const angle=e.type==='boss_titan'&&e.dash>0&&Number.isFinite(e.dx)&&Number.isFinite(e.dy)?Math.atan2(e.dy,e.dx):e.type==='charger'&&e.charging>0&&Number.isFinite(e.chargeX)&&Number.isFinite(e.chargeY)?Math.atan2(e.chargeY,e.chargeX):e.type==='shooter'&&e.attackAnim>0&&Number.isFinite(e.attackFacing)?e.attackFacing:Number.isFinite(e.facing)?e.facing:Math.atan2(player.y-e.y,player.x-e.x),bob=Math.sin(elapsed*7+e.phase);
  const spawn=Math.max(0,Math.min(1,Number.isFinite(e.spawnProgress)?e.spawnProgress:1)),spawnEase=1-Math.pow(1-spawn,3);ctx.save();ctx.translate(e.x,e.y);if(spawn<1){ctx.save();ctx.globalAlpha=.65*(1-spawn);ctx.strokeStyle=e.type==='boss'?'#ffd36e':'#72f5e5';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,e.r*(.7+spawn*1.25),0,Math.PI*2);ctx.stroke();ctx.restore()}ctx.globalAlpha*=spawn;ctx.scale(.35+.65*spawnEase,.35+.65*spawnEase);ctx.rotate(angle);
  if(e.elite){const affixData=SWARM_ELITE_AFFIXES[e.affix]||{color:'#80f7ff'};ctx.save();ctx.rotate(-angle);ctx.strokeStyle=affixData.color;ctx.shadowBlur=18;ctx.shadowColor=affixData.color;ctx.lineWidth=2;ctx.globalAlpha=.55+.25*Math.sin(elapsed*13+e.phase);for(let i=0;i<3;i++){const a=i/3*Math.PI*2+elapsed*.7,r=e.r*(1.35+.12*Math.sin(elapsed*5+i));ctx.beginPath();ctx.arc(0,0,r,a,a+.8);ctx.stroke();ctx.fillStyle='#d9ffff';ctx.fillRect(Math.cos(a)*r-1,Math.sin(a)*r-1,3,3)}ctx.restore()}
  drawEnemyModel(ctx,e,{time:elapsed,hit:e.hit>0,bossData:BOSS_DATA});
  ctx.restore();
  if(isBoss(e)){const w=150,y=e.y-e.r-27;ctx.fillStyle='rgba(4,6,12,.9)';ctx.fillRect(e.x-w/2,y,w,10);ctx.fillStyle=BOSS_DATA[e.bossTier].color;ctx.fillRect(e.x-w/2+2,y+2,(w-4)*Math.max(0,e.hp/e.maxHp),6);ctx.fillStyle='#fff';ctx.font='700 11px Chakra Petch';ctx.textAlign='center';ctx.fillText(bossDisplayName(e),e.x,y-6)}
  else if(e.elite||e.type==='brute'||e.type==='charger'){const width=e.elite?58:44,spriteSize=window.enemySpriteVisuals?.configs?.[e.type]?.size||0,barY=e.y-Math.max(e.r+14,spriteSize/2+8);ctx.fillStyle='#101522';ctx.fillRect(e.x-width/2,barY,width,5);ctx.fillStyle=e.elite?'#64efff':e.type==='charger'?'#62a4ff':'#a96cff';ctx.fillRect(e.x-width/2,barY,width*Math.max(0,e.hp/e.maxHp),5);if(e.elite){const affix=SWARM_ELITE_AFFIXES[e.affix];ctx.fillStyle=affix?.color||'#64efff';ctx.font='700 8px Chakra Petch';ctx.textAlign='center';ctx.fillText(affix?.[SwarmI18n.getLanguage()]||t('game.elite'),e.x,e.y-e.r-19)}}
}
function safeDrawEnemy(e){
  try{drawEnemy(e)}catch(error){
    if(!e.visualError)console.error('Pomijam uszkodzony model przeciwnika.',e.type,error);e.visualError=true;
    ctx.restore();ctx.save();ctx.restore()
  }
}
function drawScoutCharacter(context,x,y,facing,animation,animationTime,attackAnim){let key=animation==='run'?'walk':'idle',frame;if(attackAnim>0){key='attack';frame=onceFrame(1-attackAnim/SCOUT_ATTACK_DURATION,6)}else frame=key==='walk'?loopFrame(animationTime,SCOUT_WALK_FPS,6):0;const image=scoutImage(key);if(!image)return false;context.save();context.translate(x,y);context.rotate(facing+SCOUT_BODY_ANGLE_OFFSET);drawSpriteFrame(context,image,frame*128,0,128,128,-SCOUT_RENDER_SIZE/2,-SCOUT_RENDER_SIZE/2,SCOUT_RENDER_SIZE,SCOUT_RENDER_SIZE);context.restore();return true}
function drawWarriorCharacter(context,x,y,facing,animation,animationTime,attackAnim){let key=animation==='run'?'walk':'idle',frame;if(attackAnim>0){key='attack';frame=onceFrame(1-attackAnim/WARRIOR_ATTACK_DURATION,6)}else frame=loopFrame(animationTime,key==='walk'?WARRIOR_WALK_FPS:WARRIOR_IDLE_FPS,6);const image=warriorImage(key);if(!image)return false;context.save();context.translate(x,y);context.rotate(facing+WARRIOR_BODY_ANGLE_OFFSET);drawSpriteFrame(context,image,frame*128,0,128,128,-WARRIOR_RENDER_SIZE/2,-WARRIOR_RENDER_SIZE/2,WARRIOR_RENDER_SIZE,WARRIOR_RENDER_SIZE);context.restore();return true}
function drawDruidCharacter(context,x,y,facing,animation,animationTime,attackAnim){let key=animation==='run'?'walk':'idle',frame;if(attackAnim>0){key='attack';frame=onceFrame(1-attackAnim/DRUID_ATTACK_DURATION,6)}else frame=loopFrame(animationTime,key==='walk'?DRUID_WALK_FPS:DRUID_IDLE_FPS,6);const image=druidImage(key);if(!image)return false;context.save();context.translate(x,y);context.rotate(facing+DRUID_BODY_ANGLE_OFFSET);drawSpriteFrame(context,image,frame*128,0,128,128,-DRUID_RENDER_SIZE/2,-DRUID_RENDER_SIZE/2,DRUID_RENDER_SIZE,DRUID_RENDER_SIZE);context.restore();return true}
function warriorAttackVisualAngle(attackAngle){return attackAngle+WARRIOR_ATTACK_ANGLE_OFFSET}
function drawWarriorAttackEffect(context,x,y,attackAngle,attackAnim){const image=warriorImage('attackEffect');if(!image||attackAnim<=0)return false;const frame=onceFrame(1-attackAnim/WARRIOR_ATTACK_DURATION,6);context.save();context.translate(x,y);context.rotate(warriorAttackVisualAngle(attackAngle));drawSpriteFrame(context,image,frame*384,0,384,384,-WARRIOR_ATTACK_EFFECT_SIZE/2,-WARRIOR_ATTACK_EFFECT_SIZE/2,WARRIOR_ATTACK_EFFECT_SIZE,WARRIOR_ATTACK_EFFECT_SIZE);context.restore();return true}
function drawCharacterActor(context,{x,y,character,facing=0,animation='idle',animationTime=0,name='',hp,maxHp,attackAnim=0,attackAngle=facing,powerBuff=0}){const warriorFacing=attackAnim>0?warriorAttackVisualAngle(attackAngle)-WARRIOR_BODY_ANGLE_OFFSET:facing,spriteDrawn=character==='scout'?drawScoutCharacter(context,x,y,facing,animation,animationTime,attackAnim):character==='warrior'?drawWarriorCharacter(context,x,y,warriorFacing,animation,animationTime,attackAnim):character==='druid'&&drawDruidCharacter(context,x,y,attackAnim>0?attackAngle:facing,animation,animationTime,attackAnim),attackEffectDrawn=character==='warrior'&&drawWarriorAttackEffect(context,x,y,attackAngle,attackAnim);if(name){context.save();context.textAlign='center';context.font='700 8px Chakra Petch';context.fillStyle='#eaffff';context.fillText(name,x,y-31);if(Number.isFinite(hp)&&Number.isFinite(maxHp)){context.fillStyle='#121b28';context.fillRect(x-20,y-26,40,3);context.fillStyle='#51f6df';context.fillRect(x-20,y-26,40*Math.max(0,hp/maxHp),3)}context.restore()}}
function drawPlayer(){
  const a=Math.atan2(mouse.y+camera.y-player.y,mouse.x+camera.x-player.x);playerEchoes.forEach(e=>{ctx.save();ctx.globalAlpha=Math.max(0,e.life)*.45;drawWarriorCharacter(ctx,e.x,e.y,e.angle,'idle',elapsed,0);ctx.restore()});
  if(player.speedBuff>0){ctx.strokeStyle='#9dffcf';ctx.globalAlpha=.5;ctx.beginPath();ctx.arc(player.x,player.y,25+Math.sin(elapsed*8)*3,0,7);ctx.stroke();ctx.globalAlpha=1}drawCharacterActor(ctx,{x:player.x,y:player.y,character:chosenCharacter,facing:a,animation:(()=>{const movement=movementInput.resolve();return Math.hypot(movement.dx,movement.dy)>.1?'run':'idle'})(),animationTime:elapsed,attackAnim:player.attackAnim,attackAngle:player.attackAngle??a,abilityActive:(player.skillAnimTime||0)>0,lastAbility:player.skillAnim,powerBuff:player.powerBuff});
  if(player.teleportAnim>0){ctx.save();ctx.globalAlpha=player.teleportAnim/WARRIOR_E_DURATION;ctx.strokeStyle='#fff4bd';ctx.lineWidth=2;ctx.beginPath();ctx.arc(player.x,player.y,30+(1-player.teleportAnim/WARRIOR_E_DURATION)*32,0,7);ctx.stroke();ctx.restore()}
}

function drawSkillEffect(r){
  const progress=Math.max(0,1-r.life/r.lifeMax),fade=Math.min(1,r.life/r.lifeMax*2);ctx.save();ctx.translate(r.x,r.y);
  if(r.effect==='warriorQ'){const image=warriorImage('qEffect');if(image){ctx.globalAlpha=fade;drawSpriteFrame(ctx,image,onceFrame(progress,6)*384,0,384,384,-WARRIOR_Q_DIAMETER/2,-WARRIOR_Q_DIAMETER/2,WARRIOR_Q_DIAMETER,WARRIOR_Q_DIAMETER);ctx.restore();return}}
  if(r.effect==='warriorE'){const image=warriorImage('eEffect');if(image){ctx.rotate((r.angle||0)+WARRIOR_BODY_ANGLE_OFFSET);ctx.globalAlpha=fade;drawSpriteFrame(ctx,image,onceFrame(progress,6)*128,0,128,128,-WARRIOR_E_SIZE/2,-WARRIOR_E_SIZE/2,WARRIOR_E_SIZE,WARRIOR_E_SIZE);ctx.restore();return}}
  if(r.effect==='warriorR'){const image=warriorImage('rEffect');if(image){ctx.globalAlpha=fade;drawSpriteFrame(ctx,image,onceFrame(progress,6)*384,0,384,384,-WARRIOR_R_SIZE/2,-WARRIOR_R_SIZE/2,WARRIOR_R_SIZE,WARRIOR_R_SIZE);ctx.restore();return}}
  if(r.effect==='druidQ'){const image=druidImage('qEffect');if(image&&drawDruidEffectFrame(ctx,'qEffect',onceFrame(progress,6),DRUID_Q_SIZE,fade*.78)){ctx.restore();return}}
  if(r.effect==='druidE'){const image=druidImage('eEffect');if(image&&drawDruidEffectFrame(ctx,'eEffect',onceFrame(progress,6),DRUID_E_SIZE,fade*.58)){ctx.restore();return}}
  if(r.effect==='druidR'){const image=druidImage('rEffect');if(image&&drawDruidEffectFrame(ctx,'rEffect',onceFrame(progress,6),DRUID_R_SIZE,fade*.9)){ctx.restore();return}}
  if(r.effect==='scoutE'){const image=scoutImage('eEffect');if(image){const rect=SCOUT_E_FRAMES[onceFrame(progress,SCOUT_E_FRAMES.length)],diameter=Math.max(16,r.r*2);ctx.globalCompositeOperation='source-over';ctx.globalAlpha=fade;drawCenteredEffectFrame(ctx,image,rect,diameter);ctx.restore();return}}
  if(r.effect==='scoutR'){const image=scoutImage('rEffect');if(image){const found=SCOUT_R_TIMING.findIndex(limit=>progress<limit),rect=SCOUT_R_FRAMES[found<0?5:found],diameter=Math.max(24,r.r*2);ctx.globalCompositeOperation='source-over';ctx.globalAlpha=fade;drawCenteredEffectFrame(ctx,image,rect,diameter);ctx.restore();return}}
  ctx.globalCompositeOperation='lighter';ctx.globalAlpha=fade;ctx.shadowBlur=20;ctx.shadowColor=r.color;
  if(r.effect==='warriorQ'){ctx.rotate(progress*Math.PI*1.8);for(let blade=0;blade<3;blade++){ctx.rotate(Math.PI*2/3);ctx.strokeStyle=blade===1?'#fff4c4':'#ff9a53';ctx.lineWidth=8-blade;ctx.beginPath();ctx.arc(0,0,r.r*(.72+blade*.1),-.75,.75);ctx.stroke()}ctx.fillStyle=`rgba(255,132,69,${.18*(1-progress)})`;ctx.beginPath();ctx.arc(0,0,r.r*.72,0,7);ctx.fill()}
  else if(r.effect==='warriorR'){for(let i=0;i<10;i++){const angle=i*Math.PI/5+Math.sin(elapsed*5)*.08,distance=r.r*(.3+.55*progress);ctx.save();ctx.rotate(angle);ctx.fillStyle=i%2?'#ffcf72':'#ff6548';ctx.beginPath();ctx.moveTo(distance,-5);ctx.lineTo(distance+30,0);ctx.lineTo(distance,5);ctx.fill();ctx.restore()}ctx.strokeStyle='#fff0a3';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,r.r*.74,0,7);ctx.stroke()}
  else if(r.effect==='druidQ'){ctx.strokeStyle='#91ffad';ctx.lineWidth=3;for(let i=0;i<8;i++){ctx.save();ctx.rotate(i*Math.PI/4+progress*.7);ctx.beginPath();ctx.moveTo(18,0);ctx.bezierCurveTo(r.r*.35,-18,r.r*.72,15,r.r,0);ctx.stroke();ctx.fillStyle=i%2?'#d8ff9c':'#65e98a';ctx.beginPath();ctx.ellipse(r.r*.72,0,12,5,.25,0,7);ctx.fill();ctx.restore()}ctx.fillStyle='rgba(143,255,171,.13)';ctx.beginPath();ctx.arc(0,0,r.r*.8,0,7);ctx.fill()}
  else if(r.effect==='druidE'){ctx.rotate(elapsed*2.4);for(let i=0;i<6;i++){ctx.rotate(Math.PI/3);ctx.strokeStyle='#baffd1';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(10,0);ctx.quadraticCurveTo(r.r*.5,-18,r.r,0);ctx.stroke();ctx.fillStyle='#69e89a';ctx.beginPath();ctx.ellipse(r.r*.76,0,10,4,.3,0,7);ctx.fill()}ctx.strokeStyle='#efffd0';ctx.setLineDash([7,8]);ctx.beginPath();ctx.arc(0,0,r.r*.62,0,7);ctx.stroke();ctx.setLineDash([])}
  else if(r.effect==='druidR'){const trunk=Math.max(0,1-Math.abs(progress-.45)*2.2);ctx.strokeStyle='#a77a49';ctx.lineWidth=8;for(let i=0;i<12;i++){ctx.save();ctx.rotate(i*Math.PI/6);ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(r.r*.42,-22*trunk,r.r*.88,0);ctx.stroke();ctx.fillStyle=i%2?'#b9ff78':'#64db75';ctx.beginPath();ctx.ellipse(r.r*.65,-7,18,7,.3,0,7);ctx.fill();ctx.restore()}ctx.strokeStyle='#e6ffc1';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,r.r*.92,0,7);ctx.stroke()}
  else if(r.effect==='scoutE'){ctx.rotate(elapsed*2.8);ctx.strokeStyle='#8ffff4';ctx.lineWidth=4;ctx.setLineDash([18,10]);ctx.beginPath();ctx.arc(0,0,r.r,0,7);ctx.stroke();ctx.setLineDash([])}
  else{const flash=Math.max(0,1-progress*4);ctx.fillStyle=`rgba(190,145,255,${flash*.35})`;ctx.beginPath();ctx.arc(0,0,55+r.r*.18,0,7);ctx.fill();ctx.strokeStyle='#71fff1';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,r.r,0,7);ctx.stroke()}
  ctx.restore()
}

function drawMinimap(){const now=performance.now();if(now<minimapNextDraw)return;minimapNextDraw=now+1000/15;const started=debugProfileStart(),mw=minimap.width,mh=minimap.height,key=`${chosenMap}:${mw}:${mh}`;if(minimapStaticKey!==key){minimapStaticCanvas||=document.createElement('canvas');minimapStaticCanvas.width=mw;minimapStaticCanvas.height=mh;const bg=minimapStaticCanvas.getContext('2d');if(chosenMap==='ruins'&&window.SwarmMapVisuals?.renderRuinsMapPreview)minimapLayout=SwarmMapVisuals.renderRuinsMapPreview(bg,mw,mh)||SwarmMapVisuals.previewLayout(mw,mh);else{const scale=Math.min(mw/WORLD.w,mh/WORLD.h);minimapLayout={scale,offsetX:(mw-WORLD.w*scale)/2,offsetY:(mh-WORLD.h*scale)/2,drawW:WORLD.w*scale,drawH:WORLD.h*scale};bg.clearRect(0,0,mw,mh);bg.fillStyle='#03070d';bg.fillRect(0,0,mw,mh);bg.save();bg.translate(minimapLayout.offsetX,minimapLayout.offsetY);bg.scale(scale,scale);tracePolygon(bg,MAP_SHAPE);bg.fillStyle='#0b1b29';bg.fill();terrain.forEach(t=>{if(t.type==='water'){bg.fillStyle='#0d5064';tracePolygon(bg,t.points);bg.fill()}else if(t.type==='wall'){bg.fillStyle='#738398';bg.fillRect(t.x,t.y,t.w,t.h)}else{bg.fillStyle='#3b4657';bg.beginPath();bg.arc(t.x,t.y,t.r,0,7);bg.fill()}});bg.restore()}minimapStaticKey=key}const point=(x,y)=>window.SwarmMapVisuals?.worldToPreview?SwarmMapVisuals.worldToPreview(x,y,minimapLayout):{x:minimapLayout.offsetX+x*minimapLayout.scale,y:minimapLayout.offsetY+y*minimapLayout.scale};mapCtx.clearRect(0,0,mw,mh);mapCtx.drawImage(minimapStaticCanvas,0,0);crates.filter(c=>!c.opened).forEach(c=>{const p=point(c.x,c.y);mapCtx.fillStyle='#ffd05d';mapCtx.fillRect(p.x-1.5,p.y-1.5,3,3)});loot.forEach(i=>{const p=point(i.x,i.y);mapCtx.fillStyle=i.type==='health'?'#ff6688':i.type==='xp'?'#51f6df':'#ffd467';mapCtx.fillRect(p.x-1,p.y-1,3,3)});enemies.forEach(e=>{const p=point(e.x,e.y);mapCtx.fillStyle=isBoss(e)?BOSS_DATA[e.bossTier].color:({shooter:'#ffb45e',charger:'#62a4ff',exploder:'#ff7638',swarm:'#ed83ff',toxic:'#9cff54',trapper:'#d5ff68'}[e.type]||'#ff5277');const size=isBoss(e)?7:e.type==='swarm'?2:3;mapCtx.strokeStyle='#090511';mapCtx.lineWidth=2;mapCtx.strokeRect(p.x-size/2,p.y-size/2,size,size);mapCtx.fillRect(p.x-size/2,p.y-size/2,size,size)});if(worldEvent){const p=point(worldEvent.x,worldEvent.y);mapCtx.shadowBlur=10;mapCtx.shadowColor='#d77cff';mapCtx.fillStyle='#f09aff';mapCtx.beginPath();mapCtx.arc(p.x,p.y,5+Math.sin(elapsed*7),0,7);mapCtx.fill();mapCtx.shadowBlur=0}const cameraPoint=point(camera.x,camera.y),playerPoint=point(player.x,player.y);mapCtx.strokeStyle='#51f6df99';mapCtx.strokeRect(cameraPoint.x,cameraPoint.y,W*minimapLayout.scale,H*minimapLayout.scale);mapCtx.shadowBlur=8;mapCtx.shadowColor='#51f6df';mapCtx.fillStyle='#9ffff3';mapCtx.strokeStyle='#07111d';mapCtx.lineWidth=2;mapCtx.beginPath();mapCtx.arc(playerPoint.x,playerPoint.y,4,0,7);mapCtx.stroke();mapCtx.fill();mapCtx.shadowBlur=0;debugProfileEnd('minimap',started)}

function isVisible(x,y,margin=48){return x+margin>=camera.x&&x-margin<=camera.x+W&&y+margin>=camera.y&&y-margin<=camera.y+H}
function drawCore(){ctx.save();if(screenShake)ctx.translate((Math.random()-.5)*screenShake,(Math.random()-.5)*screenShake);ctx.fillStyle='#070b15';ctx.fillRect(0,0,W,H);ctx.translate(-camera.x,-camera.y);
  const customGround=chosenMap==='ruins'&&window.SwarmMapVisuals?.drawGround(ctx,MAP_SHAPE,WORLD);if(chosenMap!=='ruins'){const bg=ctx.createRadialGradient(player.x,player.y,40,player.x,player.y,900);if(chosenMap==='toxic'){bg.addColorStop(0,'#29421b');bg.addColorStop(.6,'#172b18');bg.addColorStop(1,'#09140c')}else{bg.addColorStop(0,'#173144');bg.addColorStop(.6,'#102232');bg.addColorStop(1,'#09131e')}tracePolygon(ctx,MAP_SHAPE);ctx.fillStyle=bg;ctx.shadowBlur=30;ctx.shadowColor='#02040a';ctx.fill();ctx.shadowBlur=0;ctx.save();tracePolygon(ctx,MAP_SHAPE);ctx.clip();ctx.strokeStyle='rgba(77,148,173,.045)';ctx.lineWidth=1;for(let x=0;x<WORLD.w;x+=120){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,WORLD.h);ctx.stroke()}for(let y=0;y<WORLD.h;y+=120){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WORLD.w,y);ctx.stroke()}ctx.restore()}drawTerrain();drawMapHazards();
  drawWorldEvent();drawCollisionDebug();tracePolygon(ctx,MAP_SHAPE);ctx.strokeStyle='#315467';ctx.lineWidth=12;ctx.stroke();ctx.strokeStyle='#51f6df22';ctx.lineWidth=2;ctx.stroke();
  scenery.forEach(s=>{if(s.x>camera.x-60&&s.x<camera.x+W+60&&s.y>camera.y-60&&s.y<camera.y+H+60)drawScenery(s)});
  crates.forEach(c=>{if(isVisible(c.x,c.y,55))drawCrate(c)});loot.forEach(item=>{if(isVisible(item.x,item.y,45))drawLoot(item)});orbs.forEach(o=>{if(!isVisible(o.x,o.y,35))return;ctx.shadowBlur=16;ctx.shadowColor='#51f6df';ctx.fillStyle='#80fff0';ctx.beginPath();ctx.moveTo(o.x,o.y-o.r);ctx.lineTo(o.x+o.r,o.y);ctx.lineTo(o.x,o.y+o.r);ctx.lineTo(o.x-o.r,o.y);ctx.fill();ctx.shadowBlur=0});
  bullets.forEach(b=>{if(!isVisible(b.x,b.y,70))return;ctx.save();ctx.translate(b.x,b.y);let spriteDrawn=false,requiresSprite=b.kind==='scoutQ'||b.kind==='scoutBullet';if(b.kind==='scoutQ'){const image=scoutImage('qProjectile');if(image){const frame=loopFrame(elapsed,SCOUT_Q_FPS,6);drawSpriteFrame(ctx,image,frame*64,0,64,64,-SCOUT_Q_SIZE/2,-SCOUT_Q_SIZE/2,SCOUT_Q_SIZE,SCOUT_Q_SIZE);spriteDrawn=true}}else if(b.kind==='scoutBullet'){const image=scoutImage('autoProjectile');if(image){const sizeScale=Math.min(1.65,Math.max(.85,(b.r||4)/4));ctx.rotate(Math.atan2(b.vy,b.vx)+SCOUT_AUTO_PROJECTILE_ANGLE_OFFSET);drawSpriteFrame(ctx,image,115,478,1026,281,-SCOUT_AUTO_PROJECTILE_LENGTH*sizeScale/2,-SCOUT_AUTO_PROJECTILE_HEIGHT*sizeScale/2,SCOUT_AUTO_PROJECTILE_LENGTH*sizeScale,SCOUT_AUTO_PROJECTILE_HEIGHT*sizeScale);spriteDrawn=true}}if(!spriteDrawn&&!requiresSprite){ctx.rotate(Math.atan2(b.vy,b.vx)+(b.kind==='boomerang'?Math.sin((b.spin||0)*.7)*.18:0));ctx.shadowBlur=18;ctx.shadowColor=b.kind==='boomerang'?'#70ff9a':'#51f6df';if(b.kind==='boomerang'){ctx.strokeStyle='#baffc9';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,15,-1.1,1.1);ctx.stroke();ctx.strokeStyle='#3fd77b';ctx.lineWidth=2;ctx.beginPath();ctx.arc(-2,0,10,-1.05,1.05);ctx.stroke();ctx.fillStyle='#e4ffd9';ctx.beginPath();ctx.moveTo(7,-14);ctx.lineTo(18,-8);ctx.lineTo(10,-4);ctx.fill()}else{ctx.fillStyle='#bafff7';ctx.beginPath();ctx.ellipse(0,0,8,3,0,0,7);ctx.fill()}}ctx.restore()});enemyBullets.forEach(b=>{if(!isVisible(b.x,b.y,80))return;if(window.enemySpriteVisuals?.drawProjectile(ctx,b,elapsed))return;if(['shooterBullet','boss_warden','boss_void','toxic_boss_fog','toxic_boss_core','nightmare'].includes(b.kind))return;ctx.shadowBlur=18;ctx.shadowColor='#ff8b38';ctx.fillStyle='#ffd078';ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,7);ctx.fill();ctx.strokeStyle='#ff7a3d';ctx.beginPath();ctx.moveTo(b.x-b.vx*.045,b.y-b.vy*.045);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.shadowBlur=0});{const enemyDrawStarted=debugProfileStart();let visibleEnemyCount=0;enemies.forEach(e=>{if(isVisible(e.x,e.y,(e.r||20)+90)){visibleEnemyCount++;safeDrawEnemy(e)}});debugCount('visibleEnemyCount',visibleEnemyCount);debugProfileEnd('enemyDraw',enemyDrawStarted)};
  rings.forEach(r=>{if(!isVisible(r.x,r.y,(r.max||r.r||0)+35))return;if(window.enemySpriteVisuals?.drawRing(ctx,r))return;if(r.visual)return;if(r.effect==='exploderExplosion'){window.enemySpriteVisuals?.drawExplosion(ctx,r);return}if(r.effect){drawSkillEffect(r);return}ctx.globalAlpha=Math.max(0,r.life);ctx.strokeStyle=r.color;ctx.lineWidth=5;ctx.shadowBlur=20;ctx.shadowColor=r.color;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,7);ctx.stroke();ctx.globalAlpha=1;ctx.shadowBlur=0});particles.forEach(p=>{if(!isVisible(p.x,p.y,20))return;ctx.globalAlpha=Math.max(0,p.life*2);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);ctx.globalAlpha=1});damageNumbers.forEach(n=>{if(!isVisible(n.x,n.y,55))return;ctx.save();ctx.globalAlpha=Math.min(1,n.life*2.5);ctx.textAlign='center';ctx.font=n.crit?'800 17px Chakra Petch':'700 12px Chakra Petch';ctx.fillStyle=n.crit?'#ffe071':'#e8f7ff';ctx.shadowBlur=n.crit?10:4;ctx.shadowColor=n.crit?'#ff9d35':'#51f6df';ctx.fillText(n.crit?'✦ '+n.value:n.value,n.x,n.y);ctx.restore()});if(window.SwarmMultiplayerSync?.shouldDrawLocalPlayer?.()!==false)drawPlayer();window.SwarmMultiplayerSync?.drawPlayers(ctx);ctx.restore();drawMinimap();drawFogOverlay()}

function draw(){const started=debugProfileStart();drawCore();debugProfileEnd('totalDraw',started)}

function drawSelectionPreviews(){
  ['scout','warrior','druid'].forEach(id=>{const canvas=document.querySelector(`#${id}Preview`),c=canvas.getContext('2d'),w=canvas.width,h=canvas.height,g=c.createRadialGradient(w*.5,h*.5,10,w*.5,h*.5,w*.42);g.addColorStop(0,id==='warrior'?'#533529':id==='druid'?'#174632':'#1d5260');g.addColorStop(1,'#050b14');c.fillStyle=g;c.fillRect(0,0,w,h);c.strokeStyle='rgba(255,255,255,.055)';for(let x=0;x<w;x+=42){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()}for(let y=0;y<h;y+=42){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}const image=id==='scout'?scoutImage('portrait'):id==='warrior'?warriorImage('portrait'):druidImage('portrait');if(image){const scale=Math.min(w/image.width,h/image.height)*.92,dw=image.width*scale,dh=image.height*scale;c.drawImage(image,(w-dw)/2,(h-dh)/2,dw,dh)}else{c.fillStyle='#718096';c.font='700 11px Chakra Petch';c.textAlign='center';c.fillText(t('assets.loading'),w/2,h/2)}});
  const map=document.querySelector('#mapPreviewCanvas'),mapPreviewContext=map.getContext('2d');if(!window.SwarmMapVisuals?.renderRuinsMapPreview?.(mapPreviewContext,map.width,map.height,{crates:SWARM_MAPS.ruins.crates})){mapPreviewContext.fillStyle='#080311';mapPreviewContext.fillRect(0,0,map.width,map.height);mapPreviewContext.fillStyle='#8fa0b3';mapPreviewContext.font='700 12px Chakra Petch';mapPreviewContext.textAlign='center';mapPreviewContext.fillText(t('assets.loadingMap'),map.width/2,map.height/2)}
  const toxic=document.querySelector('#toxicMapPreview'),tc=toxic.getContext('2d'),tw=toxic.width,th=toxic.height,tx=tw/WORLD.w,ty=th/WORLD.h,cfg=SWARM_MAPS.toxic;tc.fillStyle='#071009';tc.fillRect(0,0,tw,th);tracePolygon(tc,cfg.shape.map(([x,y])=>[x*tx,y*ty]));const tg=tc.createLinearGradient(0,0,tw,th);tg.addColorStop(0,'#29421b');tg.addColorStop(1,'#0d1810');tc.fillStyle=tg;tc.fill();
  cfg.fogZones.forEach(z=>{tc.fillStyle='rgba(121,160,116,.22)';tc.beginPath();tc.arc(z.x*tx,z.y*ty,z.r*tx,0,Math.PI*2);tc.fill()});cfg.toxicZones.forEach(z=>{tc.fillStyle='rgba(132,205,58,.7)';tc.beginPath();tc.arc(z.x*tx,z.y*ty,z.r*tx,0,Math.PI*2);tc.fill()});cfg.terrain.forEach(t=>{if(t.type==='wall'){tc.fillStyle='#758162';tc.fillRect(t.x*tx,t.y*ty,t.w*tx,t.h*ty)}else{tc.fillStyle='#46543b';tc.beginPath();tc.arc(t.x*tx,t.y*ty,t.r*tx,0,Math.PI*2);tc.fill()}});cfg.crates.forEach(c=>{tc.fillStyle='#d4aa4b';tc.fillRect(c.x*tx-3,c.y*ty-3,6,6)});tc.strokeStyle='#9ddb52';tc.lineWidth=3;tracePolygon(tc,cfg.shape.map(([x,y])=>[x*tx,y*ty]));tc.stroke()
}
renderAchievements();updateCoinDisplays();addEventListener('beforeunload',()=>saveGame());addEventListener('visibilitychange',()=>{if(document.hidden)saveGame()});refreshContinueButton();drawSelectionPreviews();const refreshMapVisualCaches=()=>{invalidateMinimap();drawSelectionPreviews();window.SwarmRefreshLobbyPreviews?.()};addEventListener('swarm-map-visuals-invalidated',refreshMapVisualCaches);addEventListener('swarm-map-visuals-ready',refreshMapVisualCaches);
let lastRuntimeError=0;
function loop(t){requestAnimationFrame(loop);if(!fpsWindowStart)fpsWindowStart=t;fpsWindowFrames++;if(t-fpsWindowStart>=500){const fps=Math.round(fpsWindowFrames*1000/(t-fpsWindowStart));if(fps!==lastDisplayedFps){fpsCounter.textContent=`FPS ${fps}`;lastDisplayedFps=fps}fpsWindowFrames=0;fpsWindowStart=t}profile.frames++;if(debugPerformance&&last){const frame=profile.values.frame||(profile.values.frame={total:0,max:0,calls:0}),ms=t-last;if(ms>16.67)debugCount('frameOver16Ms');if(ms>25)debugCount('frameOver25Ms');if(ms>33.33)debugCount('frameOver33Ms');if(ms>50)debugCount('frameOver50Ms');frame.total+=ms;frame.max=Math.max(frame.max,ms);frame.calls++}reportPerformance(t);const dt=Math.min((t-last)/1000,.033);last=t;try{if(running&&window.SwarmMultiplayerSync?.isMultiplayerMode())window.SwarmMultiplayerSync.frame(dt);else if(running&&!paused&&t>=freezeUntil)update(dt);draw()}catch(error){if(t-lastRuntimeError>2000){console.error('Klatka gry została bezpiecznie pominięta.',error);lastRuntimeError=t}}}draw();
function drawAbilityIcons(character){
  const colors={scout:['#51f6df','#4cc8ff','#a06cff'],warrior:['#ffc36c','#ff965c','#ff6558'],druid:['#70ff9a','#9dffcf','#d3ff8c']}[character];
  document.querySelectorAll('.ability canvas').forEach((canvas,index)=>{const x=canvas.getContext('2d');x.clearRect(0,0,canvas.width,canvas.height);x.strokeStyle=colors[index];x.fillStyle=colors[index]+'33';x.lineWidth=4;x.lineCap='round';x.lineJoin='round';x.shadowBlur=12;x.shadowColor=colors[index];x.beginPath();
    if(character==='scout'&&index===0){for(const y of [22,36,50]){x.moveTo(15,y);x.lineTo(53,y-8);x.moveTo(45,y-13);x.lineTo(53,y-8);x.lineTo(46,y-3)}}
    else if(character==='scout'&&index===1){x.arc(36,36,19,.35,Math.PI*1.65);x.moveTo(18,26);x.lineTo(10,20);x.moveTo(18,46);x.lineTo(10,52);x.moveTo(54,36);x.lineTo(63,36)}
    else if(character==='scout'){for(let i=0;i<12;i++){const a=-Math.PI/2+i*Math.PI/6,r=i%2?11:25;x.lineTo(36+Math.cos(a)*r,36+Math.sin(a)*r)}x.closePath()}
    else if(character==='warrior'&&index===0){x.arc(36,36,23,.2,Math.PI*1.72);x.moveTo(50,15);x.lineTo(59,17);x.lineTo(54,26);x.moveTo(22,57);x.lineTo(13,55);x.lineTo(18,46)}
    else if(character==='warrior'&&index===1){x.moveTo(12,48);x.lineTo(35,25);x.lineTo(28,25);x.moveTo(35,25);x.lineTo(35,32);x.moveTo(31,55);x.lineTo(58,28);x.lineTo(51,28);x.moveTo(58,28);x.lineTo(58,35)}
    else if(character==='warrior'){x.moveTo(16,53);x.lineTo(26,17);x.lineTo(36,29);x.lineTo(47,12);x.lineTo(57,53);x.closePath();x.moveTo(25,43);x.lineTo(49,43)}
    else if(character==='druid'&&index===0){x.moveTo(36,59);x.bezierCurveTo(8,43,13,18,36,13);x.bezierCurveTo(59,18,64,43,36,59);x.moveTo(36,49);x.lineTo(36,24);x.moveTo(25,36);x.lineTo(47,36)}
    else if(character==='druid'&&index===1){x.moveTo(13,48);x.bezierCurveTo(23,16,51,13,59,14);x.bezierCurveTo(53,42,34,57,13,48);x.moveTo(18,45);x.lineTo(50,22)}
    else{x.arc(36,36,22,0,Math.PI*2);x.moveTo(36,5);x.lineTo(36,17);x.moveTo(36,55);x.lineTo(36,67);x.moveTo(5,36);x.lineTo(17,36);x.moveTo(55,36);x.lineTo(67,36);x.moveTo(27,36);x.quadraticCurveTo(36,18,45,36);x.quadraticCurveTo(36,54,27,36)}
    x.fill();x.stroke()
  })
}
drawAbilityIcons(chosenCharacter);
